// proactive-coach-promotion / Theme C (closes-diagnose 8b1f33).
//
// Fired by Postgres trigger trg_dispatch_proactive_coach_promotion on
// every rank_promotions INSERT (migration 073). Composes an AI
// congratulation message via Gemini, writes it to ai_coach_interactions
// (the canonical chat table — offline-first: the in-app chat UI reads
// Hive, this cloud row is the upward-sync target that surfaces once the
// coach domain syncs down to the device), and sends an OneSignal push so
// the user gets the notification even when the app isn't open.
//
// 2026-05-29 audit EF-1 fix (closes-diagnose 9e1d4c): the prior version
// inserted into a nonexistent table `coach_interactions` with columns
// (role/content/metadata) that do not exist on ai_coach_interactions, so
// every promotion returned HTTP 500 BEFORE the OneSignal push — the whole
// celebration was inert. Telemetry also targeted nonexistent client_errors
// columns (message/severity) so the failure was invisible.
//
// verify_jwt=false — invoked by the Postgres trigger using the
// service_role_key from Vault. The trigger payload is internal-only.

import { serve } from "https://deno.land/std@0.208.0/http/server.ts";
import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.42.0";
import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
import {
  fetchNotificationPrefs,
  isNotificationEnabled,
} from "../_shared/notification_prefs.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY")!;
const ONESIGNAL_APP_ID = Deno.env.get("ONESIGNAL_APP_ID")!;
const ONESIGNAL_REST_API_KEY = Deno.env.get("ONESIGNAL_REST_API_KEY")!;

interface TriggerPayload {
  user_id: string;
  rank_code: string;
  achieved_at: string;
  trigger_source: string;
}

interface UserContext {
  full_name: string | null;
  primary_goal: string | null;
  current_streak_weeks: number;
  total_workouts_done: number;
}

// Rank ladder labels mirror lib/core/services/rank_ladder_data.dart.
// Hardcoded here so the Edge Function doesn't reach back into the
// client codebase. If the ladder ever changes, this map updates in
// the same commit as the client one.
// Codes + labels MUST match lib/core/services/rank_ladder_data.dart
// (kRankLadder) EXACTLY. The prior map used codes (PO2/PO1/ENS/LTJG/
// LCDR/CDR/CAPT) that exist in no ladder — 7 of 11 ranks fell through to
// the raw code in the AI prompt. Canonical ladder: SD2, SD1, LS, PO, CPO,
// MCPO, SubLt, Lt, LtCdr, Cdr, Capt.
const RANK_LABELS: Record<string, string> = {
  SD2: "Seaman 2nd Class",
  SD1: "Seaman 1st Class",
  LS: "Leading Seaman",
  PO: "Petty Officer",
  CPO: "Chief Petty Officer",
  MCPO: "Master Chief Petty Officer",
  SubLt: "Sub Lieutenant",
  Lt: "Lieutenant",
  LtCdr: "Lieutenant Commander",
  Cdr: "Commander",
  Capt: "Captain",
};

serve(async (req: Request): Promise<Response> => {
  if (req.method !== "POST") {
    return new Response("Method not allowed", { status: 405 });
  }

  // ── F44 (2026-06-07 audit) — cron/service auth gate.
  //
  // verify_jwt=false (the Postgres trigger trg_dispatch_proactive_coach_promotion
  // dispatches via pg_net, not an end-user JWT). Without a manual gate an
  // unauthenticated POST could drive Gemini cost + OneSignal push +
  // ai_coach_interactions writes to ANY user_id. The trigger sends
  // `Authorization: Bearer <service_role_jwt>` (migration 078, resolved from
  // Vault via private.morning_alert_get_service_key()), so the SAME shared
  // `isAuthorizedCronCall(req)` gate the sibling cron functions use
  // (pr-detection, streak-guardian, i-see-you-callout, re-engagement,
  // evaluate-rank-promotions, …) authenticates the existing dispatch while
  // rejecting anonymous callers. Verifies the JWT signature against
  // SUPABASE_JWT_SECRET + role-claim === 'service_role'; CRON_SECRET opaque
  // token is the escape hatch inside the helper. Reject BEFORE any
  // Gemini/push/DB work.
  if (!await isAuthorizedCronCall(req)) {
    console.warn(`[proactive-coach-promotion] unauthorized caller; status=401`);
    return jsonResponse({ error: "Unauthorized" }, 401);
  }

  let payload: TriggerPayload;
  try {
    payload = await req.json();
  } catch (_) {
    return jsonResponse({ error: "invalid json" }, 400);
  }

  const { user_id, rank_code } = payload;
  if (!user_id || !rank_code) {
    return jsonResponse({ error: "user_id + rank_code required" }, 400);
  }

  const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY);

  // Unit E — the Promotion Day toggle gates the PUSH, not the chat message.
  //
  // An earlier draft returned early before step 3, which also suppressed the
  // ai_coach_interactions insert — so opting out of a NOTIFICATION silently
  // deleted the coach's congratulation from the user's chat history. This is
  // the only guarded function that writes a persistent in-app record; its three
  // siblings write none, which is why the early return read as consistent and
  // was not (B-pass P2).
  //
  // Absent means SEND (N2): a failed lookup must never cost a promotion push.
  let pushAllowed = true;
  try {
    const prefs = await fetchNotificationPrefs(admin, [user_id]);
    pushAllowed = isNotificationEnabled(prefs, user_id, "rank_promotion");
  } catch (prefErr) {
    console.error(
      "[proactive-coach-promotion] prefs lookup failed, sending anyway:",
      prefErr,
    );
  }

  try {
    // 1. Pull user context (profile + progress snapshot).
    const userCtx = await loadUserContext(admin, user_id);

    // 2. Compose AI congrats via Gemini.
    const congrats = await composeCongrats(userCtx, rank_code);

    // 3. Write to ai_coach_interactions (canonical chat table). The
    //    proactive message is an assistant turn with no user prompt, so
    //    user_message is empty (column is NOT NULL — empty string, not
    //    null) and the congrats goes in ai_response. The proactive tag +
    //    rank_code live in the tool_calls jsonb column for downstream
    //    filtering (ai_coach_interactions has no role/metadata columns).
    const insertRes = await admin.from("ai_coach_interactions").insert({
      user_id,
      channel: "in_app",
      user_message: "",
      ai_response: congrats,
      model_used: "gemini-2.5-flash",
      tool_calls: {
        kind: "proactive_promotion",
        rank_code,
        source: "proactive-coach-promotion",
      },
    });
    if (insertRes.error) {
      await logTelemetry(admin, user_id, "proactive_coach_promotion_failed",
        `insert ai_coach_interactions: ${insertRes.error.message}`);
      return jsonResponse({ error: "coach insert failed" }, 500);
    }

    // 4. OneSignal push so the user gets a notification even when
    //    the app is closed.
    // The chat message above is written regardless; only the push is gated.
    if (pushAllowed) {
      await sendOneSignalPush(user_id, rank_code, congrats);
    } else {
      console.log(
        `[proactive-coach-promotion] user=${user_id} opted out of rank_promotion — chat message kept, push suppressed`,
      );
    }

    // 5. Success telemetry.
    await logTelemetry(admin, user_id,
      "proactive_coach_promotion_dispatched",
      `rank_code=${rank_code} congrats_len=${congrats.length}`);

    return jsonResponse({ ok: true });
  } catch (e) {
    const msg = String(e).slice(0, 500);
    await logTelemetry(admin, user_id,
      "proactive_coach_promotion_failed", msg);
    return jsonResponse({ error: msg }, 500);
  }
});

async function loadUserContext(
  admin: SupabaseClient,
  user_id: string,
): Promise<UserContext> {
  // Schema split: `full_name` lives on the `users` table (migration 001
  // / line 28 — `users.full_name text`). `primary_goal` lives on
  // `user_profile`. Querying `user_profile.full_name` returns
  // PostgrestError 42703 (column not found) — caught by Gate 18's
  // `check_reader_manifest_complete.dart` forbidden-pattern
  // `from.*user_profile.*select.*full_name`. Must hit both tables.
  const [userRes, profileRes, progressRes] = await Promise.all([
    admin.from("users").select("full_name")
      .eq("id", user_id).maybeSingle(),
    admin.from("user_profile").select("primary_goal")
      .eq("user_id", user_id).maybeSingle(),
    admin.from("user_progress")
      .select("current_streak_weeks, total_workouts_done")
      .eq("user_id", user_id).maybeSingle(),
  ]);
  // Unit C (§2.24) — surface a query failure instead of coercing to a null/0
  // context (which sends a de-personalized "Congratulations, soldier" push). This
  // runs first in the per-invocation flow, so a throw here happens BEFORE the
  // Gemini compose + the ai_coach_interactions insert + the OneSignal push.
  const ctxErr = userRes.error ?? profileRes.error ?? progressRes.error;
  if (ctxErr) throw ctxErr;
  return {
    full_name: userRes.data?.full_name ?? null,
    primary_goal: profileRes.data?.primary_goal ?? null,
    current_streak_weeks: progressRes.data?.current_streak_weeks ?? 0,
    total_workouts_done: progressRes.data?.total_workouts_done ?? 0,
  };
}

async function composeCongrats(
  ctx: UserContext,
  rankCode: string,
): Promise<string> {
  const rankLabel = RANK_LABELS[rankCode] ?? rankCode;
  const firstName = (ctx.full_name?.split(/\s+/)[0]) ?? "soldier";
  const goalCopy = goalToCopy(ctx.primary_goal);

  const systemPrompt = `You are AVYA, an AI fitness coach for the
Indian Navy-themed fitness app ICANBEFITTER. The user just promoted
to rank ${rankLabel} (code: ${rankCode}). Write a warm but
disciplined congratulation in 80-120 words.

Hard rules:
- Address them by name: "${firstName}".
- Name the specific milestone: ${ctx.total_workouts_done} workouts
  done, ${ctx.current_streak_weeks}-week streak.
- Tie motivation to their primary goal: ${goalCopy}.
- Preview what unlocks at the next rank (don't be too specific —
  the ladder is documented elsewhere).
- Military lexicon allowed sparingly (e.g. "mission", "soldier", "rank").
- NO emojis. NO bullet points. Single flowing paragraph.
- End with a forward-looking line, not a closing salutation.`;

  // Call Gemini 2.5 Flash via the public REST API. The "messages"
  // shape is mapped to Gemini's "contents" + "systemInstruction".
  const url = `https://generativelanguage.googleapis.com/v1beta/models/`
    + `gemini-2.5-flash:generateContent?key=${GEMINI_API_KEY}`;
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      systemInstruction: { parts: [{ text: systemPrompt }] },
      contents: [{
        role: "user",
        parts: [{ text:
          `Write the congrats for ${firstName} ranking up to ${rankLabel}.`
        }],
      }],
      generationConfig: {
        temperature: 0.7,
        maxOutputTokens: 256,
      },
    }),
  });
  if (!res.ok) {
    throw new Error(`Gemini ${res.status}: ${await res.text()}`);
  }
  const data = await res.json();
  const text = data?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) {
    throw new Error("Gemini returned empty content");
  }
  return String(text).trim();
}

function goalToCopy(primaryGoal: string | null): string {
  switch (primaryGoal) {
    case "lose_fat":      return "fat loss";
    case "build_muscle":  return "muscle gain";
    case "gain_strength": return "strength";
    case "general_fitness":
    default:              return "general fitness";
  }
}

async function sendOneSignalPush(
  user_id: string, rank_code: string, congrats: string,
): Promise<void> {
  // OneSignal `external_user_id` is the Supabase user_id by convention
  // (set by client on first sign-in).
  const preview = congrats.length > 80
    ? congrats.slice(0, 77) + "..."
    : congrats;
  const res = await fetch("https://onesignal.com/api/v1/notifications", {
    method: "POST",
    headers: {
      "Content-Type": "application/json; charset=utf-8",
      "Authorization": `Basic ${ONESIGNAL_REST_API_KEY}`,
    },
    body: JSON.stringify({
      app_id: ONESIGNAL_APP_ID,
      include_external_user_ids: [user_id],
      headings: { en: "🎖️ Promotion Day" },
      contents: { en: preview },
      data: { deep_link: "/ai-coach", kind: "proactive_promotion",
              rank_code },
    }),
  });
  if (!res.ok) {
    throw new Error(`OneSignal ${res.status}: ${await res.text()}`);
  }
}

async function logTelemetry(
  admin: SupabaseClient,
  user_id: string, op_type: string, message: string,
): Promise<void> {
  try {
    // client_errors columns are: error_code, error_message, op_type
    // (verified live 2026-05-29). There is NO `message`/`severity`
    // column — the prior insert silently failed, hiding EF-1.
    await admin.from("client_errors").insert({
      user_id,
      op_type,
      error_code: op_type,
      error_message: message,
    });
  } catch (_) {
    // Best-effort — never throw from telemetry.
  }
}

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

/**
 * cron_auth.ts — shared-secret auth gate for cron-dispatched Edge Functions.
 *
 * Rewritten 2026-07-26 (closes-diagnose: c3f8a1). See HISTORY at the bottom —
 * the two previous designs both failed in production, and the second failed
 * silently for roughly eight weeks.
 *
 * AUTH MODEL
 * ----------
 * A single opaque shared secret. The caller must present
 * `Authorization: Bearer <CRON_SECRET>`, where `CRON_SECRET` is an Edge
 * Function secret whose value also lives in the Vault row `cron_secret`, read
 * by `private.cron_get_secret()` and interpolated into every `cron.job`
 * command (migrations 107/108).
 *
 * WHY A SHARED SECRET RATHER THAN A JWT
 * -------------------------------------
 * This is machine-to-machine auth between pg_cron and the Edge runtime. There
 * is no user identity to carry, no claims to inspect and no delegation — a
 * signed token buys nothing here, and every JWT-shaped attempt has coupled the
 * gate to platform key management that then changed underneath it:
 *
 *   - Attempt 1 compared the token to `SUPABASE_SERVICE_ROLE_KEY`. Broke when
 *     the Vault copy and the env copy drifted (diagnose 5a65bd).
 *   - Attempt 2 verified the signature against `SUPABASE_JWT_SECRET` — a
 *     variable Supabase does not inject and **forbids creating**, because the
 *     platform reserves the `SUPABASE_` prefix for secret names. Unsatisfiable
 *     by construction; every cron call 401'd from the day it deployed.
 *
 * A string comparison has no such coupling. It is unaffected by the JWT
 * signing-key migration now underway on this project and by the deprecation of
 * `SUPABASE_ANON_KEY` / `SUPABASE_SERVICE_ROLE_KEY`.
 *
 * ⚠ THE SECRET IS THE ONLY GATE. Cron functions run `verify_jwt=false`, so
 * their URLs accept unauthenticated POSTs from anywhere and this comparison is
 * all that stands between the open internet and a privileged fan-out (push
 * sends, Gemini spend, storage deletion). `CRON_SECRET` must be long and
 * cryptographically random — `openssl rand -hex 32`. Never a memorable phrase.
 *
 * USAGE (per cron function)
 * -------------------------
 *   import { isAuthorizedCronCall } from "../_shared/cron_auth.ts";
 *
 *   Deno.serve(async (req) => {
 *     if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });
 *     if (!await isAuthorizedCronCall(req)) {
 *       return new Response(JSON.stringify({ error: "Unauthorized" }), {
 *         status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" },
 *       });
 *     }
 *     const logId = await logCronStart("<slug>");   // AFTER the gate — see below
 *     // ... handler body
 *   });
 *
 * ⚠ KEEP `logCronStart` AFTER THIS GATE. It is tempting to move it earlier so
 * that rejected calls leave a telemetry row — the 2026-07-26 batch considered
 * exactly that. Don't: on a `verify_jwt=false` endpoint it would hand every
 * anonymous caller an unauthenticated INSERT into `public.cron_call_log`.
 * Outage visibility is provided instead by `alert_cron_silence` (migration
 * 109), which alerts on the ABSENCE of successful runs and therefore needs no
 * writes from unauthenticated callers.
 */

/**
 * Constant-time string comparison.
 *
 * Both sides are hashed to a fixed 32-byte digest first, then compared with an
 * XOR-accumulate that always walks the full length. This leaks neither the
 * secret's length nor the position of the first differing byte, whereas a plain
 * `!==` short-circuits on the first mismatch and is measurable over enough
 * requests.
 *
 * Worth the few microseconds here specifically because this comparison is the
 * ONLY gate on 16 publicly-reachable endpoints (see the warning above), and the
 * secret in production is currently low-entropy by explicit accepted risk
 * (migration 107 header) — a weak secret plus a timing oracle is materially
 * worse than either alone.
 */
async function timingSafeEqual(a: string, b: string): Promise<boolean> {
  const enc = new TextEncoder();
  const [da, db] = await Promise.all([
    crypto.subtle.digest("SHA-256", enc.encode(a)),
    crypto.subtle.digest("SHA-256", enc.encode(b)),
  ]);
  const va = new Uint8Array(da);
  const vb = new Uint8Array(db);
  let diff = 0;
  for (let i = 0; i < va.length; i++) diff |= va[i] ^ vb[i];
  return diff === 0;
}

/**
 * True when the request carries `Authorization: Bearer <CRON_SECRET>`.
 *
 * False on a missing header, a malformed bearer, an unset `CRON_SECRET`, or any
 * mismatch. Never throws — safe to call without try/catch.
 */
export async function isAuthorizedCronCall(req: Request): Promise<boolean> {
  try {
    const authHeader = req.headers.get("Authorization") ?? "";
    if (!authHeader.startsWith("Bearer ")) {
      console.warn("[cron_auth] missing or malformed Authorization header");
      return false;
    }
    const token = authHeader.slice("Bearer ".length).trim();
    if (token.length === 0) {
      console.warn("[cron_auth] empty bearer token");
      return false;
    }

    // Trimmed on BOTH sides. A trailing newline pasted into the dashboard
    // secret would otherwise reject every call with no visible reason.
    const cronSecret = (Deno.env.get("CRON_SECRET") ?? "").trim();
    if (cronSecret.length === 0) {
      console.warn(
        "[cron_auth] CRON_SECRET is unset — every cron call will be rejected. " +
          "Set it in Project Settings -> Edge Functions -> Secrets, matching " +
          "the `cron_secret` Vault row exactly.",
      );
      return false;
    }

    if (!await timingSafeEqual(token, cronSecret)) {
      console.warn("[cron_auth] bearer token does not match CRON_SECRET");
      return false;
    }

    return true;
  } catch (err) {
    // Defensive — never let the auth gate crash its caller.
    console.error("[cron_auth] unexpected error:", err);
    return false;
  }
}

/*
 * HISTORY
 * -------
 * 2026-05-11 (7ad0c4)  Gate introduced; 8 cron functions were publicly callable.
 * 2026-05-12 (audit P0) Vault `service_role_key` row was empty, so the header
 *                       went out as `Bearer null` → 401 on every tick, 12 jobs.
 * 2026-05-15 (5a65bd)  Env-equality check broke on Vault/env key drift. That
 *                       write-up proposed "replace the brittle env-equality
 *                       check with a JWT signature+role decode" as the
 *                       permanent class fix.
 * 2026-05-16           The class fix shipped. It depended on
 *                       `SUPABASE_JWT_SECRET`, which cannot exist. The fix
 *                       made the bug permanent instead of ending it.
 * 2026-07-26 (c3f8a1)  Discovered: ~8 weeks of total cron silence. Three
 *                       safeguards had failed together — telemetry sat behind
 *                       the failing gate, pg_cron reports `succeeded` for any
 *                       dispatch regardless of HTTP status, and the health
 *                       alert computed a rate from the table the failure kept
 *                       empty. Replaced with this shared-secret gate; the
 *                       `deno.land/x/jose` dependency is gone with it, closing
 *                       a remote-dep-rot risk this repo has already been bitten
 *                       by (feedback_mistake_remote_dep_rot).
 */

/**
 * notification_prefs.ts — the single server-side reader of a user's
 * notification preferences (Unit E).
 *
 * THE RULE: ABSENT ⇒ SEND (decision N2)
 * ------------------------------------
 * A missing key, a missing snapshot, a failed query, a malformed value — every
 * one of them means SEND. Only a literal `enabled === false` silences a push.
 * Nobody loses a notification to a sync gap or a transient database error; the
 * cost of the opposite default is a user who turned something off and can never
 * work out why it still arrives.
 *
 * WHY latest-desc AND NOT today-pinned
 * ------------------------------------
 * The obvious implementation pins `snapshot_date` to today. It is inert.
 * Measured against live data: 91 snapshot rows across 17 users, exactly **1**
 * row for today, only 3 users fresh within three days, and the stalest user's
 * newest row was two months old. A today-pinned read would therefore find
 * nothing for 16 of 17 users and fall through to SEND — i.e. the toggles would
 * still do nothing, while looking implemented.
 *
 * It is worse than merely ineffective for `re-engagement`, whose targets are BY
 * DEFINITION people who have not opened the app recently. Their snapshot can
 * never be today's. A today-pinned guard there is not "usually inert", it is
 * guaranteed inert.
 *
 * So: order by snapshot_date DESC and keep the FIRST row per user — the user's
 * most recent known preferences, however old. Shape copied from
 * `weekly-recap-ready/index.ts:163-185`, which already had it right.
 *
 * WHY BATCHED
 * -----------
 * One query per run, not one per user. `re-engagement` already runs a
 * multi-query loop per candidate; adding a per-user `.single()` there would
 * multiply the round-trips on the function with the largest candidate set.
 */

// deno-lint-ignore no-explicit-any
type SupabaseLike = any;

/** Per-user preference maps, keyed by user_id. */
export type PrefsByUser = Map<string, Record<string, unknown>>;

/**
 * Most-recent notification preferences for each of [userIds].
 *
 * Returns an EMPTY map on any failure — callers then send to everyone, which is
 * the fail-safe direction (N2). Never throws: an exception escaping here would
 * abort a whole cron run for a preferences lookup.
 */
export async function fetchNotificationPrefs(
  client: SupabaseLike,
  userIds: string[],
): Promise<PrefsByUser> {
  const out: PrefsByUser = new Map();
  if (!userIds || userIds.length === 0) return out;

  try {
    const { data, error } = await client
      .from("user_daily_snapshots")
      .select("user_id, snapshot_json")
      .in("user_id", userIds)
      .order("snapshot_date", { ascending: false });

    if (error) {
      console.error(
        "[notification_prefs] fetch failed, defaulting to SEND:",
        error.message,
      );
      return out;
    }

    for (const row of (data ?? []) as Record<string, unknown>[]) {
      const uid = row.user_id as string | undefined;
      if (!uid || out.has(uid)) continue; // first row wins = most recent
      const snap = (row.snapshot_json ?? {}) as Record<string, unknown>;
      const prefs = snap.notification_preferences;
      out.set(
        uid,
        prefs && typeof prefs === "object" && !Array.isArray(prefs)
          ? prefs as Record<string, unknown>
          : {},
      );
    }
    return out;
  } catch (err) {
    // Transport-level rejection (DNS, reset, timeout before any HTTP
    // response) rejects the promise rather than returning { error }. Same
    // reasoning as _shared/subscription.ts — without this, one network blip
    // aborts the entire cron run instead of degrading to "send to everyone".
    console.error("[notification_prefs] threw, defaulting to SEND:", err);
    return out;
  }
}

/**
 * True when [key] should be SENT to [userId].
 *
 * Only an explicit `enabled === false` returns false. Absent user, absent key,
 * non-object entry, non-boolean `enabled` — all send.
 */
export function isNotificationEnabled(
  prefs: PrefsByUser,
  userId: string,
  key: string,
): boolean {
  const userPrefs = prefs.get(userId);
  if (!userPrefs) return true;

  const entry = userPrefs[key];
  if (!entry || typeof entry !== "object" || Array.isArray(entry)) return true;

  return (entry as Record<string, unknown>).enabled !== false;
}
